head.script:
/**
 * 페이지 로딩 이벤트
 */
scwin.onpageload = function() {
	//지역은 부산, 인천만 표시
	for(var i=0; i<dlt_location.getRowCount(); i++){
		var location = dlt_location.getCellData(i, "COMCOD");

		if(location == "KRPUS" || location == "KRINC"){
			dlt_location.setCellData(i, "VISIBLE", "true");
		} else {
			dlt_location.setCellData(i, "VISIBLE", "false");
		}
	}

	sbx_location.setVisibleColumn("VISIBLE", "false");
};


scwin.btn_apply_onclick = function(e) {

	// dma_master.set("location", "KRPUS");
	// dma_master.set("terminal", "test");
	// dma_master.set("description", "test desc");

	dma_master.set("location", "KRCHO");
	dma_master.set("terminal", "test");
	dma_master.set("description", "test desc");
};

scwin.checkVal = function() {
	return WebSquare.wUnit.getJq('#wq_uuid_8').val() == 'KRCHO';
}
scwin.checkVal2 = function() {
	return WebSquare.wUnit.getDomById('sbx_location_label').innerText == 'CHEONAN, KOREA';
}	
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_apply').click()");
	WebSquare.wUnit.addCommand("pause", "400");

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
